import React from 'react'
import { CContainer, CHeader } from '@coreui/react'
import { Alert } from 'react-bootstrap';

import { useState } from 'react';

const AppHeader = () => {
  const [showConfirmation, setShowConfirmation] = useState(false);

  const handleClearData = () => {
    localStorage.clear();
    window.location.reload();
  };

  const handleConfirmClearData = () => {
    handleClearData();
    setShowConfirmation(false);
  };

  const handleCancelClearData = () => {
    setShowConfirmation(false);
  };

  return (
    <CHeader position="sticky" className="mb-4">
      <CContainer fluid>
        {/* ...existing code... */}
        {!showConfirmation && (
          <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
            <button onClick={() => setShowConfirmation(true)}>Clear Data</button>
          </div>
        )}
        {showConfirmation && (
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', width: '100%' }}>
            <div style={{ width: '100%' }}>
              <Alert variant="danger">
                  <p style={{ marginLeft: '0' }}>Are you sure you want to clear the data?</p>
                <div style={{ display: 'flex', justifyContent: 'flex-end', marginTop:'-40px' }}>
                  <button onClick={handleConfirmClearData}>Confirm</button>
                  <button onClick={handleCancelClearData}>Cancel</button>
                </div>
              </Alert>
            </div>
          </div>
        )}
      </CContainer>
    </CHeader>
  );
};

export default AppHeader
